"""Regenerate the compact SpaceX report from hash-verified pinned evidence."""
from pathlib import Path
import json,hashlib,urllib.request,argparse,statistics
ROOT=Path(__file__).resolve().parents[1]
AUTH='a467f6f85cdd6684739943612fb9e1bf72e592f2';AGENT='151240887b1a77587cd75516cdb77b111fcb2b9d'
URL=f'https://raw.githubusercontent.com/nift-experiments/spacex/{AUTH}/investigation/evidence/performance-summary.json'
SHA='12100e8297ee76dcd02331ce4c9efe7412e027293001eedf75c952120ea51f54'
p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path);a=p.parse_args()
raw=a.evidence.read_bytes() if a.evidence else urllib.request.urlopen(URL).read()
assert hashlib.sha256(raw).hexdigest()==SHA,'Pinned benchmark evidence hash mismatch'
d=json.loads(raw);projects=d['projects'];names=['spacex','spacex-agent']
for project in projects.values():
 for scenario in project['scenarios'].values():
  assert len(scenario['samples'])==5
  for metric in ['wallSeconds','maxProcessRssMiB']:
   values=[s[metric] for s in scenario['samples']];v=scenario[metric];assert statistics.median(values)==v['median'] and min(values)==v['min'] and max(values)==v['max']
labels={'warm-full':'Warm full','fresh-application-state':'Fresh state','unchanged':'Unchanged','ordinary-page-edit':'One mission','homepage-edit':'Homepage','shared-layout':'Shared layout','navigation-edit':'Navigation','css-edit':'Shared CSS','frontend-js-edit':'JS + cache key','media-metadata-edit':'Runtime JSON','three-page-edit':'Three missions','route-add':'Route added','route-rename':'Route renamed','route-delete':'Route deleted'}
full=['warm-full','fresh-application-state','unchanged'];edits=['ordinary-page-edit','three-page-edit','homepage-edit','shared-layout','navigation-edit','css-edit','frontend-js-edit','media-metadata-edit','route-add','route-rename','route-delete']
def value(name,key,metric):return projects[name]['scenarios'][key][metric]
def chart(keys,metric,title,maximum,unit):
 s=f'<figure class="telemetry"><figcaption>{title}</figcaption><div class="legend"><span>Nift authored</span><span>Nift rendered</span></div><div class="axis"><span>0 {unit}</span><span>{maximum:g} {unit}</span></div>'
 for k in keys:
  s+=f'<div class="trace"><div class="label">{labels[k]}</div><div class="tracks">'
  for n in names:
   v=value(n,k,metric)['median'];dec=3 if metric=='wallSeconds' else 1;s+=f'<div class="track"><div class="rail"><div class="bar" style="width:{v/maximum*100:.4f}%"></div></div><span class="value">{v:.{dec}f} {unit}</span></div>'
  s+='</div></div>'
 return s+'</figure>'
def distribution(n,k,metric):
 v=value(n,k,metric);dec=3 if metric=='wallSeconds' else 1;return f"{v['median']:.{dec}f} ({v['min']:.{dec}f}–{v['max']:.{dec}f})"
rows=''
for k in full+edits:rows+=f'<tr><td>{labels[k]}</td><td>{distribution(names[0],k,"wallSeconds")}</td><td>{distribution(names[1],k,"wallSeconds")}</td><td>{distribution(names[0],k,"maxProcessRssMiB")}</td><td>{distribution(names[1],k,"maxProcessRssMiB")}</td></tr>'
def link(path,label,agent=False):
 repo='spacex-agent' if agent else 'spacex';sha=AGENT if agent else AUTH;return f'<li><a href="https://github.com/nift-experiments/{repo}/blob/{sha}/{path}">{label} ↗</a></li>'
evidence=''.join([link('investigation/evidence/reference-routes.json','Frozen public-route inventory'),link('investigation/BASELINE.md','Public reference and acquisition provenance'),link('investigation/MEDIA-POLICY.md','Offline / remote media policy'),link('investigation/evidence/media-preservation.json','Media preservation record'),link('asset-manifest.json','Pinned maintained asset manifest'),link('investigation/evidence/final-parity-scope.json','Accepted parity scope and qualifications'),link('investigation/evidence/responsive-wrapper-checkpoint.json','Four-viewport geometry evidence'),link('investigation/evidence/header-menu-scope-checkpoint.json','Header, dropdown and menu evidence'),link('investigation/evidence/performance-summary.json','All time / RSS samples and distributions'),link('investigation/evidence/final-incremental-correctness.json','Authored incremental / forced equality'),link('investigation/evidence/final-incremental-correctness.json','Rendered incremental / forced equality',True),link('investigation/evidence/final-fresh-clone.json','Authored fresh-clone proof'),link('investigation/evidence/final-fresh-clone.json','Rendered fresh-clone proof',True),link('investigation/evidence/publication-size.json','Publication bytes and repeated CSS'),link('investigation/PERFORMANCE.md','Authored evaluation and reproduction'),link('investigation/PERFORMANCE.md','Rendered evaluation and reproduction',True),link('investigation/INIT-FEEDBACK.md','Migration-init lessons')])
evidence += '<li><a href="https://github.com/nift-experiments/lab-evidence/blob/8c1d417a1772d58559a23c0768c3d106dc6c2ff4/sites/spacex/20261012/frozen-reference-manifest.json">Complete acquired-reference hash manifest ↗</a></li><li><a href="https://github.com/nift-experiments/lab-evidence/tree/8c1d417a1772d58559a23c0768c3d106dc6c2ff4/sites/spacex/20261012/performance">Raw time/RSS reports and build logs ↗</a></li><li><a href="https://github.com/nift-experiments/lab-evidence/blob/8c1d417a1772d58559a23c0768c3d106dc6c2ff4/sites/spacex/20261012/README.md">Canonical campaign scope and reference identity ↗</a></li>'
html='''<header class="mast"><a href="@path('/')">Nift Labs / flight test SX-01</a><span>Independent public-output reconstruction</span></header><main id="main"><div class="hero"><div class="orbit" aria-hidden="true"></div><div class="eyebrow">Reference acquired / SpaceX.com</div><h1>A public site.<br>Two source<br><em>trajectories.</em></h1><p>The original SpaceX.com source and build system are not publicly available. This experiment reconstructs the observable public site as two Nift projects. It does not claim to migrate or benchmark SpaceX’s private codebase.</p><p class="footnote">Frozen routes and browser evidence first. Publication telemetry second. Independent research; no SpaceX endorsement.</p></div><div class="launchline"></div><div class="acquired"><div><strong>805</strong><span>unique frozen public routes</span></div><div><strong>918</strong><span>tracked publication outputs</span></div><div><strong>4</strong><span>actual viewport fixtures</span></div></div><nav class="sectionnav" aria-label="Report sections"><a href="#parity">01 / parity</a><a href="#models">02 / source models</a><a href="#build">03 / build</a><a href="#iteration">04 / iteration</a><a href="#media">05 / media</a><a href="#judgment">06 / judgment</a><a href="#evidence">07 / evidence</a></nav>
<section id="parity"><span class="seq">01 / reference lock</span><h2>Preserve the visible flight.</h2><p class="lead">A visual, media-heavy marketing site is a different workload from a documentation corpus. Full-bleed video, changing header states, forms, galleries and WebGL trackers all belong to the reconstruction.</p><ul class="states"><li><b>Homepage / settled geometry</b><span>Seven heading boxes, footer and total body height match both models at 1440×1000, 768×1000, 390×844 and 320×844.</span></li><li><b>Tracker / native browser runtime</b><span>Vehicle and follow-Dragon heading, canvas, telemetry and footer geometry match all four fixtures. Representative pointer drag and keyboard activation work.</span></li><li><b>Navigation / scrolling contract</b><span>Mobile down-scroll hides the header; up-scroll restores it. Delivered dropdown positioning and nav-owned menu scrolling are retained.</span></li><li><b>Corpus / publication audit</b><span>829 pages and redirects plus 89 HLS manifests. All 805 reference routes represented; zero unclassified missing local references.</span></li><li><b>Forms / local behavior</b><span>Source-derived required fields, distinct email grammars, conditional fields and the lead form’s 449/450/500 counter boundaries.</span></li><li><b>Page families / representative states</b><span>712 missions, 143 galleries / 411 slides, 21 crew missions, 22 multi-webcast lists and 3,059 career records are inventoried.</span></li></ul><div class="scope">Parity maturity was accepted for closeout. Exact compared geometry is not exhaustive animated-pixel, physical-touch, all-filter or private-backend certification. Private submissions/CAPTCHA/newsletter success are unavailable and never fabricated. Two inherited malformed references remain classified. Browser codec and external-playback qualifications remain below.</div></section>
<section id="models"><span class="seq">02 / maintained source</span><h2>Two ways to own the reconstruction.</h2><div class="two"><div><span class="tag">Nift spacex / authored source</span><h3>Keep repeatable content authoritative.</h3><p>Structured JSON, prose and native HTML partials maintain mission, homepage and careers content. Shared Nift templates compose them. This is not a Markdown conversion benchmark.</p><pre class="pipeline">Maintained structured content + partials
→ Nift dependency evaluation / composition
→ HTML and HLS publication</pre></div><div><span class="tag">Nift spacex-agent / rendered source</span><h3>Maintain the recovered HTML directly.</h3><p>Agents edit maintained rendered markup with shared native partials. No recovery script or renderer runs during routine publication.</p><pre class="pipeline">Maintained rendered HTML + partials
→ Nift dependency evaluation / composition
→ HTML and HLS publication</pre></div></div><p>Both retain ordinary browser JavaScript for animation, validation, native/HLS video and WebGL telemetry. Internal links, images, videos, fonts and runtime assets use <code>&#64;path</code>; Nift handles publication paths, not browser physics.</p></section>
<section id="build"><span class="seq">03 / build telemetry</span><h2>The public reference is not a timing participant.</h2><p>No private SpaceX build measurements exist in this experiment. The two columns below compare the reconstructed Nift projects only.</p>FULL_CHARTS<p>Five serialized samples per scenario on an Intel i7-12700H, 20 logical CPUs, Nift 4.10.0 with the maintained automatic thread setting. Medians; zero-based linear scales. Maximum individual process RSS is measured by GNU time, not aggregate memory. No sampled tree-RSS cohort was captured.</p><p>Warm full uses <code>nift build --all</code>. Fresh application state clears generated Nift dependency metadata before <code>nift build</code>; it does not flush OS caches. Unchanged uses the same normal production command. Full and fresh build all 918 outputs.</p><div class="scope">These are complete routine publication times for this architecture: dependency checks, maintained-source evaluation, path resolution, templates and writes. There is no routine converter, frontend bundler, backend compiler, search stage, asset acquisition or postprocessor. Pinned media acquisition is setup-only; maintained static files are already under public. Nift’s internal operations are one measured phase, not separately timed internals.</div></section>
<section id="iteration"><span class="seq">04 / changed-input telemetry</span><h2>Measure the next edit, including memory.</h2>EDIT_CHARTS<p>One mission rebuilds one output; three missions rebuild three; homepage changes rebuild three including aliases. Shared layout, navigation, CSS and JS/cache-key changes rebuild 783 pages. Runtime JSON is already a maintained publication asset and requires no HTML rebuild. A route add or rename builds one output; deletion removes the old output.</p><p>These are controlled maintained-source probes. Shared markup/JS probes add harmless comments, CSS adds an unused rule, and metadata adds valid JSON whitespace. Route tracking and source mutation occur before the timed publication command. Every incremental workload reports RSS from those same five samples.</p><details><summary>All medians and observed ranges / seconds and MiB</summary><div class="tablewrap"><table><thead><tr><th>Scenario</th><th>Authored time / s</th><th>Rendered time / s</th><th>Authored RSS / MiB</th><th>Rendered RSS / MiB</th></tr></thead><tbody>ROWS</tbody></table></div></details><p>Ten lifecycle correctness checks per project match incremental and forced bytes, including source restoration and absence of renamed/deleted outputs. Fresh GitHub checkouts after pinned setup reproduce all 918 generated files exactly and serve homepage/JS through the normal preview script.</p><h3>Keep the remaining cost visible.</h3><p>The rendered model is faster in full publication; it does not uniformly reduce peak RSS. Shared-shell fan-out remains the major iteration cost. Output contains approximately 102 MB HTML, including roughly 81 MB repeated inline CSS, plus 2.18 MB external JavaScript. Inline CSS is already included in HTML bytes, not an additional asset total. Externalizing appropriate shared styles is future work requiring its own parity pass.</p><p>No Nift core changes, benchmark-specific cache, thread tuning or speculative optimization layer were introduced. The approximately one-second publication profile did not justify destabilizing the accepted rendering architecture.</p></section>
<section id="media"><span class="seq">05 / preservation boundary</span><h2>Playback reference, not a video archive.</h2><div class="two"><div><span class="tag">Offline-preserved</span><h3>What the observed site needs.</h3><p>HTML, delivered bundles, images, fonts, hero/background video, posters, thumbnails, tracker textures and captured initial HLS playback windows. Seven pinned maintained-asset releases represent 3,072 paths / approximately 3.858 GB of accepted bytes.</p></div><div><span class="tag">Remote-referenced</span><h3>What the download catalogue needs.</h3><p>The manifest records 61 remote-referenced media entries (about 346.6 GB in declared content lengths). The 320.6+ GiB download-only catalogue remains at original public URLs with route association, role, content type, content length, status and available response metadata. Large payloads were not mirrored just to demonstrate working download links.</p></div></div><p>Uncaptured HLS tails retain canonical URLs; complete offline streams are not claimed. Original HEVC bytes remain intact, including a clip unsupported by this test browser. External YouTube URLs remain intact; offline parity preview blocks third-party playback. Background videos were not replaced with posters to manufacture parity.</p><p>The maintained projects each acquire their required publication assets once. Heavy canonical reference, release transport and benchmark logs stay outside Labs. Normal build/serve does not read sibling reference directories.</p></section>
<section id="judgment"><span class="seq">06 / engineering judgment</span><h2>Prefer the authored source of truth.</h2><div class="two"><div><span class="tag">Humans + agents both edit</span><p class="decision">Preferred: Nift <code>spacex</code> — authored source.</p><p>Structured authoritative records and shared native templates are easier to review and maintain than coordinating repeated rendered markup.</p></div><div><span class="tag">Agents implement / humans direct</span><p class="decision">Preferred: Nift <code>spacex</code> — authored source.</p><p>Ordinary iteration is already sub-second. The rendered model’s full-build advantage does not outweigh the clearer content model for this corpus.</p></div></div><p>If reconstruction effort is already paid, the same preference holds. Nift <code>spacex-agent</code> remains a viable direct-HTML maintenance model and the faster full-publication path. This judgment compares these two reconstructed repositories, never SpaceX’s unseen private source.</p><h3>Is this kind of site a good Nift fit?</h3><p class="lead">Yes, within the demonstrated public surface: Nift composes a substantial static route corpus cheaply while native browser runtimes retain the media, animation and tracker behavior.</p><p>The work also shows the real reconstruction cost, extensive parity work, CSS duplication and unavailable private-service boundaries. It supports Nift’s architectural suitability for this class of public site, not a claim that SpaceX should migrate its private implementation.</p><h3>Migration-init dogfooding</h3><p><code>nift init --migration</code> guidance should explicitly support frozen observable-output reconstruction when source is unavailable, remote-only download media, authored/rendered recovery choices, scoped browser parity and absent incumbent build benchmarks. Those are recorded guidance lessons; no core change was made during this experiment.</p></section>
<section id="evidence"><span class="seq">07 / retained evidence</span><h2>Reproduce the flight test.</h2><p>Source closeouts: authored <code>AUTH_SHORT</code>, rendered <code>AGENT_SHORT</code>. Timing/parity build revisions are separately recorded as <code>5c94f5e</code> / <code>0691f43</code>; closeout adds diagnostic scripts, evidence and documentation without changing publication inputs.</p><p><a href="https://github.com/nift-experiments/spacex/tree/AUTH">Nift spacex — authored repository</a> · <a href="https://github.com/nift-experiments/spacex-agent/tree/AGENT">Nift spacex-agent — rendered repository</a></p><ul class="links">EVIDENCE</ul><pre class="pipeline">python3 scripts/setup-assets.py  # one-time pinned acquisition
nift build
python3 scripts/serve-preview.py --port 4173
# optional offline-service preview: --offline-services</pre><p class="footnote">Final experiment accepted within recorded scope. This report preserves limitations and remaining profiling opportunities; they belong to future tooling work rather than an open-ended polishing campaign.</p></section></main><footer class="signature"><a href="@path('sites/')">← All website experiments</a><span>Nift Labs / independent flight-test report / 2026-10-12</span></footer>'''
html=html.replace('FULL_CHARTS',chart(full,'wallSeconds','Complete publication / elapsed seconds',1.8,'s')+chart(full,'maxProcessRssMiB','Complete publication / peak individual RSS',120,'MiB')).replace('EDIT_CHARTS',chart(edits,'wallSeconds','Changed input / elapsed seconds',1.8,'s')+chart(edits,'maxProcessRssMiB','Changed input / peak individual RSS',100,'MiB')).replace('ROWS',rows).replace('EVIDENCE',evidence).replace('AUTH_SHORT',AUTH[:7]).replace('AGENT_SHORT',AGENT[:7]).replace('AUTH',AUTH).replace('AGENT',AGENT)
(ROOT/'content/sites/spacex/index.html').write_text(html+'\n')
print('Rendered SpaceX report from verified pinned evidence:',SHA)
